# region: digest
def digest(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, floor_=2):
    return [v for v in xs if v >= floor_]

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs):
    return [v for v in xs if v % 2 == 0]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(fold(emit(sift(render(digest(raw))))))

